#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Card 17: make the platform a Meta Tech Provider (.scratch/mvp/issues/17-meta-tech-provider.md).
# Source for every step: docs/research/whatsapp.md §1.
# Run from the repo root: scripts/meta-tech-provider-wizard.sh
# Business verification takes up to 14 business days and App Review needs it approved,
# so come back later with FROM=11 scripts/meta-tech-provider-wizard.sh to skip to App Review.

# The library already defaulted ENV_FILE to .env, which holds the Meta Emulator values.
ENV_FILE=.env.meta
TOTAL_STAGES=11
FROM="${FROM:-1}"

# ask_required KEY "Prompt" asks until a value is given: an empty ID would break every later stage.
ask_required() {
  local attempt
  for attempt in 1 2 3; do
    ask "$1" "$2"
    [[ -n "${!1}" ]] && return
    warn "Esse valor é obrigatório."
  done
  warn "Sem valor para $1. Rode de novo quando tiver: FROM=$_STAGE_INDEX scripts/meta-tech-provider-wizard.sh"
  exit 1
}

# ask_secret_required KEY "Prompt" is ask_required with hidden input.
ask_secret_required() {
  local attempt
  for attempt in 1 2 3; do
    ask_secret "$1" "$2"
    [[ -n "${!1}" ]] && return
    warn "Esse valor é obrigatório."
  done
  warn "Sem valor para $1. Rode de novo quando tiver: FROM=$_STAGE_INDEX scripts/meta-tech-provider-wizard.sh"
  exit 1
}

stage_prerequisites() {
  stage "Pré-requisitos"
  say "Antes de abrir qualquer painel, tenha em mãos:"
  step "Uma conta pessoal no Facebook com autenticação em dois fatores ligada."
  step "Um business portfolio (business.facebook.com) com o nome legal e o CNPJ da empresa."
  step "Um site público com política de privacidade (o App Review pede a URL)."
  step "Documentos da empresa (cartão CNPJ, conta de luz ou extrato com o endereço) para a verificação."
  step "Um número dedicado à plataforma que NÃO esteja em nenhum WhatsApp (nem o comum nem o Business)."
  warn "Se o número já estiver num app WhatsApp, apague a conta nele antes da etapa 4."
  pause "Tudo pronto? Enter para continuar"
}

stage_app() {
  stage "Criar o app Business"
  open_url "https://developers.facebook.com/apps/creation/"
  step "Crie um app com o caso de uso 'Connect with customers through WhatsApp'."
  step "Quando pedir, conecte o business portfolio da empresa."
  step "Em Use cases > Customize, abra 'Tech Provider onboarding' e siga o checklist."
  step "Em App settings > Basic, copie o App ID."
  ask_required META_APP_ID "Cole o App ID:"
  step "Na mesma página, clique em 'Show' no App secret e copie."
  ask_secret_required META_APP_SECRET "Cole o App secret:"
  write_env META_APP_ID "$META_APP_ID"
  write_env META_APP_SECRET "$META_APP_SECRET"
  note "Ainda em Basic: preencha ícone, URL da política de privacidade e categoria. O App Review pede."
  pause
}

stage_business_verification() {
  stage "Pedir a business verification"
  open_url "https://business.facebook.com/settings/security"
  step "No Security Center do portfolio, clique em 'Start verification'."
  step "Preencha nome legal, endereço, telefone, e-mail e site exatamente como no CNPJ."
  step "Envie os documentos se forem pedidos."
  warn "Editar esses dados depois reinicia a análise. Confira antes de enviar."
  note "A análise leva até 14 dias úteis. As etapas 4 a 10 não dependem dela; a 11 depende."
  pause "Enviou? Enter para continuar"
}

stage_phone_number() {
  stage "Número da plataforma no WABA"
  open_url "https://developers.facebook.com/apps/${META_APP_ID}/"
  step "No menu do app, vá em WhatsApp > API Setup."
  step "Clique em 'Add phone number', escolha o WABA da empresa (ou crie um) e defina o display name."
  step "Verifique o número pelo código recebido por SMS ou ligação."
  step "De volta ao API Setup, selecione o número em 'From' e copie o Phone number ID e o WhatsApp Business Account ID."
  warn "Não use o número de teste da Meta: ele não serve para clientes reais."
  ask_required META_PLATFORM_PHONE_NUMBER_ID "Cole o Phone number ID:"
  ask_required META_PLATFORM_WABA_ID "Cole o WhatsApp Business Account ID:"
  write_env META_PLATFORM_PHONE_NUMBER_ID "$META_PLATFORM_PHONE_NUMBER_ID"
  write_env META_PLATFORM_WABA_ID "$META_PLATFORM_WABA_ID"
  pause
}

stage_system_user_token() {
  stage "Token permanente (system user)"
  say "O token temporário do API Setup expira em 24h. A API precisa de um que não expire."
  open_url "https://business.facebook.com/settings/system-users"
  step "Adicione um system user com papel Admin."
  step "Em 'Assign assets', dê Full control no app e no WABA da plataforma."
  step "Clique em 'Generate token', escolha o app, expiração 'Never' e as permissões"
  step "  whatsapp_business_messaging e whatsapp_business_management. Copie o token."
  ask_secret_required META_ACCESS_TOKEN "Cole o token:"
  write_env META_ACCESS_TOKEN "$META_ACCESS_TOKEN"
  pause
}

stage_register_number() {
  stage "Registrar o número na Cloud API"
  say "O registro ativa o número na Cloud API e define um PIN de verificação em duas etapas."
  ask_secret_required REGISTER_PIN "Escolha um PIN de 6 dígitos (guarde num cofre de senhas):"
  if confirm "Registrar o número ${META_PLATFORM_PHONE_NUMBER_ID} agora?"; then
    curl -sS -X POST "https://graph.facebook.com/v24.0/${META_PLATFORM_PHONE_NUMBER_ID}/register" \
      -H "Authorization: Bearer ${META_ACCESS_TOKEN}" \
      -H 'Content-Type: application/json' \
      -d "{\"messaging_product\":\"whatsapp\",\"pin\":\"${REGISTER_PIN}\"}"
    printf '\n'
    note "Esperado: {\"success\":true}. Se vier um erro, leia a mensagem e rode de novo com FROM=6."
  else
    SKIPPED+=("registrar o número (FROM=6 scripts/meta-tech-provider-wizard.sh)")
  fi
  pause
}

stage_payment_method() {
  stage "Forma de pagamento no WABA"
  say "Mensagens de autenticação são pagas (R\$ 0,035 cada no Brasil). Sem cartão, o login não envia."
  open_url "https://business.facebook.com/wa/manage/home/"
  step "No WhatsApp Manager, abra a conta da plataforma e adicione uma forma de pagamento."
  note "O nome exato do menu muda com frequência. Procure por 'Payment methods' ou 'Pagamentos'."
  pause "Cadastrou? Enter para continuar"
}

stage_graph_and_verify_token() {
  stage "Graph URL e verify token"
  write_env META_GRAPH_URL "https://graph.facebook.com/v24.0"
  if [[ -z "$(_existing META_VERIFY_TOKEN || true)" ]]; then
    write_env META_VERIFY_TOKEN "$(openssl rand -hex 32)"
  else
    note "META_VERIFY_TOKEN já existe em ${ENV_FILE}; mantido."
  fi
  note "O webhook (URL pública + este verify token) é configurado no deploy, cards 18 e 19."
  pause
}

stage_login_template() {
  stage "Template login_code"
  say "A API cria o template login_code ao subir. Rode em outro terminal, a partir de apps/api:"
  say "  bun --env-file=../../.env --env-file=../../${ENV_FILE} src/index.ts"
  pause "Quando a API tiver subido, pare com Ctrl-C lá e volte aqui. Enter para conferir o status"
  curl -sS "https://graph.facebook.com/v24.0/${META_PLATFORM_WABA_ID}/message_templates?name=login_code&fields=name,language,status" \
    -H "Authorization: Bearer ${META_ACCESS_TOKEN}"
  printf '\n'
  note "PENDING é normal: a aprovação leva até 24h. Confira de novo depois com FROM=9."
  pause
}

stage_review_videos() {
  stage "Vídeos do App Review"
  say "O App Review pede um vídeo por permissão. Grave a tela (Cmd-Shift-5) com:"
  step "whatsapp_business_messaging: enviar uma mensagem pelo cURL do API Setup e mostrá-la chegando no WhatsApp."
  step "whatsapp_business_management: criar um template no WhatsApp Manager."
  open_url "https://developers.facebook.com/apps/${META_APP_ID}/"
  pause "Gravou os dois? Enter para continuar"
}

stage_app_review() {
  stage "Pedir o App Review"
  if ! confirm "A business verification já foi aprovada?"; then
    SKIPPED+=("App Review: espere a verificação e rode FROM=11 scripts/meta-tech-provider-wizard.sh")
    return
  fi
  open_url "https://developers.facebook.com/apps/${META_APP_ID}/app-review/permissions/"
  step "Peça Advanced access para whatsapp_business_messaging e whatsapp_business_management. Só essas duas."
  step "Em cada uma, anexe o vídeo correspondente e descreva o uso:"
  note "  messaging: enviamos o código de login e mensagens do Profissional para os Clientes dele."
  note "  management: criamos os templates de Orçamento, Visita e Cobrança no WABA de cada Profissional."
  step "Envie para análise. A média é de 24h."
  note "Quando for aprovado, marque os critérios de aceite no card 17."
  pause
}

STAGES=(
  stage_prerequisites
  stage_app
  stage_business_verification
  stage_phone_number
  stage_system_user_token
  stage_register_number
  stage_payment_method
  stage_graph_and_verify_token
  stage_login_template
  stage_review_videos
  stage_app_review
)

banner "Virar Tech Provider da Meta"

# Values from earlier runs, so FROM can skip ahead.
for key in META_APP_ID META_PLATFORM_PHONE_NUMBER_ID META_PLATFORM_WABA_ID META_ACCESS_TOKEN; do
  printf -v "$key" '%s' "$(_existing "$key" || true)"
done

_STAGE_INDEX=$((FROM - 1))
for stage_function in "${STAGES[@]:$((FROM - 1))}"; do
  "$stage_function"
done

finish
